import { useState } from 'react';
import styles from './InvestmentForm.module.css';

const InvestmentForm = ({ onAddInvestment }) => {
  const [formData, setFormData] = useState({
    brand: '',
    processor: '',
    generation: '',
    initialCost: '',
    salePrice: '',
  });

  // ... (marcas, procesadores y generaciones se mantienen igual)

  const handleSubmit = (e) => {
    e.preventDefault();
    const profit = parseFloat(formData.salePrice) - parseFloat(formData.initialCost);
    const investmentDate = new Date().toISOString(); // Fecha de la inversión

    // Crear objeto de inversión completo
    const newInvestment = {
      ...formData,
      id: Date.now(), // ID único
      date: investmentDate,
      initialCost: parseFloat(formData.initialCost),
      salePrice: parseFloat(formData.salePrice),
      profit,
    };

    // 1. Guardar en el historial de inversiones
    const investmentsHistory = JSON.parse(localStorage.getItem('investmentsHistory')) || [];
    localStorage.setItem(
      'investmentsHistory',
      JSON.stringify([...investmentsHistory, newInvestment])
    );

    // 2. Actualizar finanzas en localStorage
    const currentFinance = JSON.parse(localStorage.getItem('financialData')) || {
      totalIncome: 0,
      totalExpenses: 0,
      balance: 0,
      currentBalance: 0,
    };

    const updatedFinance = {
      ...currentFinance,
      totalIncome: currentFinance.totalIncome + parseFloat(formData.salePrice),
      totalExpenses: currentFinance.totalExpenses + parseFloat(formData.initialCost),
      balance: currentFinance.balance + profit,
      currentBalance: currentFinance.currentBalance + profit,
    };

    localStorage.setItem('financialData', JSON.stringify(updatedFinance));

    // 3. Pasar la inversión al componente padre (si es necesario)
    onAddInvestment(newInvestment);

    // 4. Resetear formulario
    setFormData({
      brand: '',
      processor: '',
      generation: '',
      initialCost: '',
      salePrice: '',
    });
  };

  // ... (el resto del componente se mantiene igual)
};

export default InvestmentForm;
